//! Fixtures shared by the Qwen tower's tests.
//!
//! Everything a test needs is generated here rather than checked in as a blob,
//! with one exception: the geometry comes from the recorded checkpoint config
//! and the recorded tower manifest, because a hand-written pair would let the
//! tests keep passing after the real one changed. The recording was produced
//! from the checkpoint rather than from this code: a manifest generated by the
//! loader would agree with whatever the loader got wrong.

use std::path::PathBuf;

use shiso_core::{HfConfig, VisionConfig};

/// The recorded checkpoint config, the single source of the geometry and the
/// media token ids every test asserts against.
pub(crate) const RECORDED_CONFIG: &str =
    include_str!("../../../../../test-vectors/loader/qwen35-config.json");

/// The vision block of the recorded checkpoint config.
pub(crate) fn vision_config() -> VisionConfig {
    HfConfig::from_json_str(RECORDED_CONFIG)
        .expect("the recorded config parses")
        .vision_config()
        .expect("the recorded config's vision block parses")
        .expect("the recorded config carries a vision block")
}

/// The recorded vision tower: what the local checkpoint's shard actually held
/// when it was read, names and shapes.
const RECORDED_TOWER: &str =
    include_str!("../../../../../test-vectors/vision/qwen35-vision-tower-manifest.json");

/// The recorded tower manifest, parsed.
pub(crate) fn recorded_tower() -> serde_json::Value {
    serde_json::from_str(RECORDED_TOWER).expect("the recorded tower manifest is valid JSON")
}

/// The local checkpoint directory, when this machine has one.
///
/// `None` is the normal answer on a machine with no model checked out, and the
/// tests that need one skip rather than fail. Nothing downloads anything.
pub(crate) fn checkpoint_dir() -> Option<PathBuf> {
    let path = PathBuf::from(std::env::var("SHISO_TEST_MODEL_OPTIQ").ok()?);
    path.is_dir().then_some(path)
}

// -- a synthetic tower with real numbers in it ------------------------------
//
// The loader's own fixture next door fills its payload with a per-tensor byte
// pattern, which is exactly right for proving a tensor reached the device
// intact and useless for running arithmetic over. This one writes brain-float
// values a host reference can recompute from, and hands back the same values as
// a tree, so the encoder's output can be checked against a reading of the same
// weights rather than against a second run of itself.

/// Header constants of the standalone container format.
const TOWER_MAGIC: u32 = 0x4655_4747;
/// Container version this fixture writes.
const TOWER_VERSION: u32 = 3;
/// Payload alignment the container uses when it declares none.
const TOWER_ALIGN: usize = 32;
/// Metadata type id for an unsigned 32-bit value.
const TOWER_KV_U32: u32 = 4;
/// Metadata type id for a string.
const TOWER_KV_STR: u32 = 8;
/// Tensor type id for brain-float, the one width the encoder's kernels read.
const TOWER_BF16: u32 = 30;

/// An architecture the published contract says nothing about, so a tower loads
/// on whatever dimensions it declares rather than being judged against a shape
/// it was never meant to have.
pub(crate) const SYNTHETIC_ARCH: &str = "synthetic-vision";

/// The 16 bits a brain-float keeps of an `f32`, by truncation.
///
/// The fixture writes these bits and every host reference reads the value back
/// through [`widen_bf16`], so the pair never depends on which rounding the host
/// chose: the device and the reference see one value, not two roundings of one.
pub(crate) fn narrow_bf16(value: f32) -> u16 {
    u16::try_from(value.to_bits() >> 16).expect("the high half of a float is sixteen bits")
}

/// One brain-float widened, exactly as the kernels widen it.
pub(crate) fn widen_bf16(bits: u16) -> f32 {
    f32::from_bits(u32::from(bits) << 16)
}

/// A deterministic fixture in `[-1, 1)`, from a small linear generator.
///
/// Fixed rather than random so a failure reproduces value for value. The value
/// is built out of sixteen bits read as a signed integer rather than divided out
/// of a float, which keeps the whole helper exact and free of a narrowing cast.
pub(crate) fn signal(len: usize, seed: u32) -> Vec<f32> {
    let mut state = seed | 0x9E37_79B9;
    (0..len)
        .map(|_| {
            state = state.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);
            let bits = u16::try_from((state >> 12) & 0xffff).expect("masked to sixteen bits");
            f32::from(i16::from_ne_bytes(bits.to_ne_bytes())) / 32_768.0
        })
        .collect()
}

/// One tensor's worth of fixture values, already rounded to what the device
/// will hold.
///
/// Weights are kept small and normalization scales near one, so the tower's
/// activations stay in the range a real one works in. A fixture whose weights
/// were unit-scale would drive the residual stream into the thousands within a
/// couple of layers, and a comparison there measures cancellation rather than
/// the kernels.
fn tower_values(name: &str, len: usize, seed: u32) -> Vec<f32> {
    let is_norm_scale = name.ends_with(".weight")
        && name
            .rsplit('.')
            .nth(1)
            .is_some_and(|part| part.starts_with("norm"));
    signal(len, seed)
        .into_iter()
        .map(|v| {
            let scaled = if is_norm_scale {
                1.0 + 0.1 * v
            } else {
                0.05 * v
            };
            widen_bf16(narrow_bf16(scaled))
        })
        .collect()
}

/// Writes a standalone tower of `dims` with usable numbers in it.
///
/// Returns the file, which deletes itself, and the values every tensor holds,
/// in the tree the encoder walks.
pub(crate) fn synthetic_tower(
    dims: crate::qwen35::vision::dims::VisionDims,
    seed: u32,
) -> (
    tempfile::NamedTempFile,
    crate::qwen35::vision::manifest::TowerTree<Vec<f32>>,
) {
    use std::io::Write;

    let prefix = crate::qwen35::vision::manifest::SIDECAR_PREFIX;
    let manifest = crate::qwen35::vision::manifest::TowerManifest::build(prefix, dims);
    let specs: Vec<_> = manifest.iter().cloned().collect();

    let mut next = seed;
    let values: crate::qwen35::vision::manifest::TowerTree<Vec<f32>> = manifest
        .clone()
        .try_map(|spec| {
            next = next.wrapping_add(7);
            let len = usize::try_from(spec.elements()).expect("a fixture tensor fits");
            Ok::<_, std::convert::Infallible>(tower_values(spec.name(), len, next))
        })
        .expect("generating fixture values cannot fail");

    let mut out = Vec::new();
    put_u32(&mut out, TOWER_MAGIC);
    put_u32(&mut out, TOWER_VERSION);
    put_u64(&mut out, count(specs.len()));

    let metadata = tower_metadata(dims);
    put_u64(&mut out, count(metadata.len() + 1));
    put_str(&mut out, "general.architecture");
    put_u32(&mut out, TOWER_KV_STR);
    put_str(&mut out, SYNTHETIC_ARCH);
    for (key, value) in &metadata {
        put_str(&mut out, key);
        put_u32(&mut out, TOWER_KV_U32);
        put_u32(&mut out, *value);
    }

    let mut offset = 0u64;
    for spec in &specs {
        put_str(&mut out, spec.name());
        // The container writes the fastest-varying axis first, which is the
        // reverse of how the manifest states a shape.
        let axes: Vec<u64> = spec.shape().iter().rev().copied().collect();
        put_u32(&mut out, narrow(axes.len()));
        for axis in &axes {
            put_u64(&mut out, *axis);
        }
        put_u32(&mut out, TOWER_BF16);
        put_u64(&mut out, offset);
        offset += spec.elements() * 2;
    }
    while out.len() % TOWER_ALIGN != 0 {
        out.push(0);
    }
    for tensor in values.iter() {
        for value in tensor {
            out.extend_from_slice(&narrow_bf16(*value).to_le_bytes());
        }
    }

    let mut file = tempfile::NamedTempFile::new().expect("a temporary file");
    file.write_all(&out).expect("the fixture is written");
    file.flush().expect("the fixture is flushed");
    (file, values)
}

/// The dimension metadata the loader reads back out of the container.
fn tower_metadata(dims: crate::qwen35::vision::dims::VisionDims) -> Vec<(String, u32)> {
    let geometry = dims.geometry();
    [
        ("block_count", dims.depth()),
        ("embedding_length", dims.hidden()),
        ("feed_forward_length", dims.intermediate()),
        ("attention.head_count", dims.heads()),
        ("projection_length", dims.out_hidden()),
        ("patch_size", geometry.patch_size()),
        ("temporal_patch_size", geometry.temporal_patch_size()),
        ("spatial_merge_size", geometry.spatial_merge_size()),
        ("position_embedding_count", dims.position_embeddings()),
    ]
    .into_iter()
    .map(|(suffix, value)| (format!("{SYNTHETIC_ARCH}.{suffix}"), narrow(value)))
    .collect()
}

/// A fixture count as the container writes it.
fn count(value: usize) -> u64 {
    u64::try_from(value).expect("a fixture count fits")
}

/// A fixture dimension as the container writes it.
fn narrow(value: usize) -> u32 {
    u32::try_from(value).expect("a fixture dimension fits")
}

fn put_u32(out: &mut Vec<u8>, value: u32) {
    out.extend_from_slice(&value.to_le_bytes());
}

fn put_u64(out: &mut Vec<u8>, value: u64) {
    out.extend_from_slice(&value.to_le_bytes());
}

fn put_str(out: &mut Vec<u8>, value: &str) {
    put_u64(out, count(value.len()));
    out.extend_from_slice(value.as_bytes());
}
